contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will try to call getTokens sending `amount` wei. We check two cases: call succeeds or reverts.
    // Inputs:
    //  - amount: Ether to send to getTokens (must be available in this contract)
    //  - priorValueAdjust: a boolean to optionally call finishDistribution first to change distribution state
    function run(uint256 amount, bool priorValueAdjust) public payable {
        require(address(this).balance >= amount);

        // Read initial observable state for this test contract address
        address tester = address(this);
        uint256 balBefore = c.balanceOf(tester);
        bool blackBefore = c.blacklist(tester);
        uint256 distributedBefore = c.totalDistributed();
        uint256 remainingBefore = c.totalRemaining();

        // Optionally finish distribution to create a branching behavior (caller decides input)
        if (priorValueAdjust) {
            // try to finish distribution; may revert if not owner, so catch it
            bool finReverted;
            try c.finishDistribution() returns (bool ok) { finReverted = false; } catch { finReverted = true; }
            // no further action — we just influence c's distributionFinished state if owner
            (void)finReverted; // silence unused
        }

        // Perform the call and capture whether it reverted
        bool reverted;
        try c.getTokens{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 balAfter = c.balanceOf(tester);
        bool blackAfter = c.blacklist(tester);
        uint256 distributedAfter = c.totalDistributed();
        uint256 remainingAfter = c.totalRemaining();
        uint256 contractEth = address(c).balance;

        // General rule asserted in one condition:
        // If the call succeeded then:
        //   - the tester's balance increased by exactly distributedAfter - distributedBefore (the new tokens given to tester)
        //   - tester is blacklisted (blackAfter == true)
        //   - totalDistributed increased and totalRemaining decreased correspondingly
        // If the call reverted then:
        //   - no change to tester's balance or blacklist
        //   - totalDistributed and totalRemaining unchanged
        // Additionally, after success the contract's ETH balance is at least previous plus amount (it may be withdrawn later by owner so we only assert non-decrease on success).

        assert(
            // success case
            (!reverted &&
                blackAfter == true &&
                // distributed increase equals change in totalDistributed
                distributedAfter >= distributedBefore &&
                remainingAfter <= remainingBefore &&
                // balance increment equals the difference in distributed that is attributable (non-strict: balAfter - balBefore equals how much c distributed to this address, which is bounded by distributedAfter-distributedBefore)
                balAfter >= balBefore &&
                (balAfter - balBefore) <= (distributedAfter - distributedBefore)
            )
            ||
            // revert case
            (reverted &&
                balAfter == balBefore &&
                blackAfter == blackBefore &&
                distributedAfter == distributedBefore &&
                remainingAfter == remainingBefore
            )
        );
    }

    // Allow contract to receive Ether for funding the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to call getTokens sending `amount` wei. We check two outcomes: revert or success.
    // Inputs:
    //  - amount: Ether to send to getTokens (must be available in this contract)
    //  - tryFinish: if true, attempt to call finishDistribution() before getTokens to allow reaching both branches
    function run(uint256 amount, bool tryFinish) public payable {
        require(address(this).balance >= amount);

        address tester = address(this);
        uint256 balBefore = c.balanceOf(tester);
        bool blackBefore = c.blacklist(tester);
        uint256 distributedBefore = c.totalDistributed();
        uint256 remainingBefore = c.totalRemaining();

        // Optionally try to finish distribution; not critical if it reverts (onlyOwner), catch via try/catch
        if (tryFinish) {
            try c.finishDistribution() returns (bool) {
                // no-op on success
            } catch {
                // ignore revert
            }
        }

        // Call getTokens with provided Ether and capture whether it reverted
        bool reverted;
        try c.getTokens{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(tester);
        bool blackAfter = c.blacklist(tester);
        uint256 distributedAfter = c.totalDistributed();
        uint256 remainingAfter = c.totalRemaining();

        // Single assert expressing the general invariant
        assert(
            (
                // If reverted: nothing observable about balances/blacklist/distributed/remaining changed
                reverted &&
                balAfter == balBefore &&
                blackAfter == blackBefore &&
                distributedAfter == distributedBefore &&
                remainingAfter == remainingBefore
            )
            ||
            (
                // If succeeded: caller's balance did not decrease, caller is blacklisted,
                // totalDistributed increased (or stayed same in edge cases) and totalRemaining decreased (or stayed same),
                // and the caller's token increase is at most the increase in totalDistributed.
                !reverted &&
                balAfter >= balBefore &&
                blackAfter == true &&
                distributedAfter >= distributedBefore &&
                remainingAfter <= remainingBefore &&
                (balAfter - balBefore) <= (distributedAfter - distributedBefore)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to call getTokens sending `amount` wei. We observe before/after via public getters.
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        address tester = address(this);
        uint256 balBefore = c.balanceOf(tester);
        bool blackBefore = c.blacklist(tester);
        uint256 distributedBefore = c.totalDistributed();
        uint256 remainingBefore = c.totalRemaining();

        bool reverted;
        // State-changing call must be a top-level statement
        try c.getTokens{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(tester);
        bool blackAfter = c.blacklist(tester);
        uint256 distributedAfter = c.totalDistributed();
        uint256 remainingAfter = c.totalRemaining();

        // Exactly one assert expressing the general invariant.
        assert(
            (
                // If reverted: observable values unchanged
                reverted &&
                balAfter == balBefore &&
                blackAfter == blackBefore &&
                distributedAfter == distributedBefore &&
                remainingAfter == remainingBefore
            )
            ||
            (
                // If succeeded: caller becomes blacklisted, balance did not decrease,
                // totalDistributed increased by at least the caller's balance gain, and totalRemaining did not increase.
                !reverted &&
                blackAfter == true &&
                balAfter >= balBefore &&
                distributedAfter >= distributedBefore &&
                // distributed increase covers caller gain: (distributedAfter - distributedBefore) >= (balAfter - balBefore)
                (distributedAfter - distributedBefore) >= (balAfter - balBefore) &&
                // totalRemaining cannot increase when tokens distributed
                remainingAfter <= remainingBefore
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0) && to != address(0));
        // ensure this contract is allowed to act as 'from' by simulating approvals if needed:
        // Note: we cannot impersonate other addresses; msg.sender for calls is this contract.
        // The ERC20 transfer function uses msg.sender as sender, so to test transfer we must call c.transfer from this contract.
        // We'll treat 'from' as the recipient of prior tokens by distributing some tokens to it via getTokens if possible.

        // Prepare state: attempt to ensure 'from' has some balance by calling c.distr via getTokens path is not possible for arbitrary 'from'.
        // Instead, we will observe balances before, attempt the transfer from this contract acting as sender, and reason about effects.

        // Read balances before
        uint256 balThisBefore = c.balanceOf(address(this));
        uint256 balToBefore = c.balanceOf(to);

        // Attempt transfer: as per ERC20, transfer uses msg.sender as sender (this contract). So transfer should move amount from this contract to 'to'.
        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balThisAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);

        // General rule: if transfer succeeded then this contract's balance decreased by amount and receiver's increased by amount (bounds permitting);
        // if it reverted then both balances are unchanged.
        // Because transfer requires _to != address(0) and _amount <= balances[msg.sender], on success we expect exact changes.
        assert(
            (reverted && balThisAfter == balThisBefore && balToAfter == balToBefore)
            || (!reverted && balThisBefore >= amount && balThisAfter + amount == balThisBefore && balToAfter == balToBefore + amount)
        );
    }

    // allow receiving ETH if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address spender, uint256 value) public payable {
        require(spender != address(0));

        // read allowance before
        uint256 before = c.allowance(address(this), spender);

        // attempt to approve
        bool reverted;
        try c.approve(spender, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read allowance after
        uint256 after = c.allowance(address(this), spender);

        // If approve reverted, allowance must remain unchanged; otherwise it must equal the requested value.
        assert( (reverted && after == before) || (!reverted && after == value) );
    }

    receive() external payable {}
}

